mapper.select:
SELECT lq.id, lq.employee_id, e.name AS employee_name, lq.leave_type_id, lt.leave_name AS leave_type_name, lq.year, lq.total_quota, lq.used_quota, lq.frozen_quota, lq.available_quota, lq.expiry_date, lq.create_time, lq.update_time FROM hr_leave_quota lq LEFT JOIN hr_employee e ON lq.employee_id = e.id LEFT JOIN hr_leave_type lt ON lq.leave_type_id = lt.id WHERE lq.tenant_id = #{tenantId} AND lq.deleted = 0
AND lq.employee_id = #{employeeId}
AND lq.year = #{year}
ORDER BY lq.leave_type_id, lq.year DESC
